import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.8tqBsFWt.js";const k=JSON.parse('{"title":"Task Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/tasks.md","filePath":"reference/tools/tasks.md"}'),r={name:"reference/tools/tasks.md"};function n(c,e,d,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="task-tools" tabindex="-1">Task Tools <a class="header-anchor" href="#task-tools" aria-label="Permalink to &quot;Task Tools&quot;">​</a></h1><hr><h2 id="create_task" tabindex="-1">create_task <a class="header-anchor" href="#create_task" aria-label="Permalink to &quot;create_task {#create_task}&quot;">​</a></h2><p>Create a new global task type (work-category label used across projects, e.g. Design, Development, Admin). <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>task_name</code>, <code>is_billable</code> (optional, default false)</p><blockquote><p>VERA checks for a case-insensitive duplicate before creating. After creation, VERA will offer to enable the task on a named project if one was mentioned.</p></blockquote><p><strong>Returns</strong>: <code>task_id</code>, <code>task_name</code>, <code>is_billable</code></p><hr><h2 id="rename_task" tabindex="-1">rename_task <a class="header-anchor" href="#rename_task" aria-label="Permalink to &quot;rename_task {#rename_task}&quot;">​</a></h2><p>Rename a task globally. The new name appears on all historical time entries immediately. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>old_name</code>, <code>new_name</code></p><p><strong>Returns</strong>: <code>task_id</code>, <code>old_name</code>, <code>new_name</code>, <code>entries_affected</code></p><hr><h2 id="update_task" tabindex="-1">update_task <a class="header-anchor" href="#update_task" aria-label="Permalink to &quot;update_task {#update_task}&quot;">​</a></h2><p>Update a task&#39;s <code>is_billable</code> flag. <strong>Owner only.</strong> VERA shows a before/after confirmation before calling this tool.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>task_id</code>, <code>is_billable</code></p><blockquote><p>Archived tasks are rejected as write targets — unarchive first if needed.</p></blockquote><p><strong>Returns</strong>: <code>task_id</code>, <code>task_name</code>, <code>is_billable</code></p><hr><h2 id="archive_task" tabindex="-1">archive_task <a class="header-anchor" href="#archive_task" aria-label="Permalink to &quot;archive_task {#archive_task}&quot;">​</a></h2><p>Archive a task so it no longer appears in menus or as a write target. Historical time entries referencing it are preserved. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>task_name</code></p><blockquote><p>Hard fails if the task is currently enabled on any active project — disable it on those projects first. Use <code>unarchive_task</code> to restore.</p></blockquote><hr><h2 id="unarchive_task" tabindex="-1">unarchive_task <a class="header-anchor" href="#unarchive_task" aria-label="Permalink to &quot;unarchive_task {#unarchive_task}&quot;">​</a></h2><p>Restore an archived task to active status. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>task_name</code></p><hr><h2 id="list_tasks" tabindex="-1">list_tasks <a class="header-anchor" href="#list_tasks" aria-label="Permalink to &quot;list_tasks {#list_tasks}&quot;">​</a></h2><p>List all task types. Active tasks only by default.</p><p><strong>Reads from</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>include_archived</code> (optional bool)</p><p><strong>Returns</strong>: array of <code>{ id, name, is_billable, status }</code> for each task</p><hr><h2 id="enable_task_for_project" tabindex="-1">enable_task_for_project <a class="header-anchor" href="#enable_task_for_project" aria-label="Permalink to &quot;enable_task_for_project {#enable_task_for_project}&quot;">​</a></h2><p>Enable a task for a specific project, making it available when logging time to that project. <strong>Owner or assigned PM</strong> (PM-of-project gated — a Manager who is not the PM is denied).</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>06. Project_Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code>, <code>task_name</code>, <code>budget_hours</code> (optional), <code>alert_threshold</code> (optional, default 80)</p><p><strong>Permission note (updated #1090):</strong> Now <strong>deterministic (DET)</strong>. Wired in the extractor (<code>object_nouns: [&#39;task&#39;]</code>), resolver (PM-of-project <code>pmOrOwnerGate</code>), and a server-side instant-fire gate in <code>index.js</code>. Non-PM manager denial is deterministic (no model turn). Missing slots fall through to the model.</p><p>Natural phrasings: <code>&quot;enable the Design task on CityCore&quot;</code>, <code>&quot;turn on the Design task on CityCore&quot;</code>.</p><hr><h2 id="disable_task_for_project" tabindex="-1">disable_task_for_project <a class="header-anchor" href="#disable_task_for_project" aria-label="Permalink to &quot;disable_task_for_project {#disable_task_for_project}&quot;">​</a></h2><p>Disable a task for a specific project. <strong>Owner or assigned PM</strong> (PM-of-project gated — a Manager who is not the PM is denied).</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>06. Project_Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code>, <code>task_name</code></p><p><strong>Permission note (updated #1090):</strong> Now <strong>deterministic (DET)</strong> with a confirm gate. Wired in the extractor (<code>object_nouns: [&#39;task&#39;]</code>), resolver (<code>pmOrOwnerGate</code>), and a confirm→fire gate in <code>index.js</code>. <code>&quot;remove the design task from X&quot;</code> routes here — no longer hijacked by <code>delete_entry</code>. Non-PM manager denial is deterministic.</p><p>Natural phrasings: <code>&quot;disable the Design task on CityCore&quot;</code>, <code>&quot;remove the design task from CityCore&quot;</code>, <code>&quot;turn off the Design task on CityCore&quot;</code>.</p>',59)])])}const g=o(r,[["render",n]]);export{k as __pageData,g as default};
